```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    /// DropSeen: keep only items whose `id` is absent from the 'seen' store.
    ///
    /// The store handle is scoped to 'seen' by the host, read-only: `get` is the
    /// only function this node holds, so it can ask about ids it was handed but
    /// cannot mutate or enumerate the store. An id present in the store means the
    /// item was recorded on a prior run and is dropped; absent means it is kept.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
